#include <utility>
#include <iostream>

int main() {
    std::pair<int, char> p1 = {1, 'b'};
    std::pair<int, char> p2 = {2, 'a'};
    std::pair<int, char> p3 = {1, 'c'};

    // Lexicographical comparison
    std::cout << (p1 < p2) << "\n"; // True (1 < 2)
    std::cout << (p1 < p3) << "\n"; // True (1 == 1, then 'b' < 'c')
    std::cout << (p1 == std::pair{1, 'b'}) << "\n"; // True
}
